# Generated by jlbind::use_jlbind(). Binds the package's functions (in
# R/jlbind-wrappers.R) to the compiled Julia library.
.onLoad <- function(libname, pkgname) {
  jlbind::bind_client(pkgname)
}

# Plain R data to save a `point` as (see `r_saved_by` in JLBind).
.jlbind_saved_state <- function(x) {
  list(x = point_x(x))
}
